parameters.jsCode:
// Robust JSON extraction from Ollama output
let raw = $json.message?.content ?? "";

// 1) remove markdown fences if present
raw = raw.replace(/```json/gi, "").replace(/```/g, "").trim();

// 2) extract the first JSON object block
const start = raw.indexOf("{");
const end = raw.lastIndexOf("}");

if (start === -1 || end === -1 || end <= start) {
  return [{ requirements: { error: "No JSON object found", raw } }];
}

const jsonText = raw.slice(start, end + 1);

let requirements;
try {
  requirements = JSON.parse(jsonText);
} catch (e) {
  return [{ requirements: { error: "JSON parse failed", jsonText, raw } }];
}

return [{ requirements }];

const jobTitle = $node["On form submission"].json.job_title || "";
const company = $node["On form submission"].json.company || "";
const fitgap = $node["FitGap - Ollama"].json.message?.content || "";
const evidence = $node["Evidence - RAG"].json.answer || "";
const citations = $node["Evidence - RAG"].json.citations || [];

const prompt =
`You are AI PM Ops Copilot.

Task: Generate final outputs using ONLY the inputs included below.

OUTPUTS REQUIRED:
A) 4 ATS-friendly resume bullets tailored to this role
B) 120-word LinkedIn outreach message
C) 6 interview questions + 1-line STAR pointers

RULES:
- Do NOT invent experience.
- Each resume bullet must include at least one citation like [1].
- If a requirement is a GAP, write a learning-plan bullet instead.

ROLE:
Job Title: ${jobTitle}
Company: ${company}

FIT/GAP TABLE:
${fitgap}

EVIDENCE (RAG answer):
${evidence}

CITATIONS (JSON):
${JSON.stringify(citations, null, 2)}
`;

return [{ prompt }];

const req = $node["Parse Requirements JSON"].json.requirements || {};
const evidence = $node["Evidence - RAG"].json.answer || "";
const citations = $node["Evidence - RAG"].json.citations || [];

const prompt =
`Build a Fit/Gap matrix for Jeevan Deep Borugadda.

Rules:
- Use ONLY the EVIDENCE below when claiming experience.
- If evidence is missing, mark it as GAP.
- Output a Markdown table with columns:
  Requirement | Evidence (with citations like [1]) | Fit (High/Med/Low) | Gap Notes | Suggested Resume Bullet

REQUIREMENTS JSON:
${JSON.stringify(req, null, 2)}

EVIDENCE (RAG answer):
${evidence}

CITATIONS (JSON):
${JSON.stringify(citations, null, 2)}
`;

return [{ prompt }];
